// src/Home.js

import React, { useState, useEffect } from 'react';
import './Home.css'; // Import the CSS file
import { assets } from './assets/assets';

function Home() {
  const [category, setCategory] = useState("All");
  const [cartItems, setCartItems] = useState(JSON.parse(localStorage.getItem('cartItems')) || {});
  const [menuList, setMenuList] = useState([]);
  const [foodList, setFoodList] = useState([]);
  const [isLoginPopupVisible, setIsLoginPopupVisible] = useState(false);
  const [isForgotPasswordPopupVisible, setIsForgotPasswordPopupVisible] = useState(false);
  const [isSignup, setIsSignup] = useState(false);
  const [showProfileOptions, setShowProfileOptions] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    if (window.menu_list) {
      setMenuList(window.menu_list);
    }
    if (window.food_list) {
      setFoodList(window.food_list);
    }

    loadCartFromLocalStorage();
    updateCartIndicator();
    renderMenu();
    renderFoodItems();
    renderCartItems();
    updateCartTotal();

    if (window.setOnLoginSuccess) {
      window.setOnLoginSuccess(fetchCartOnLogin);
    }

    const userId = localStorage.getItem('userId');
    if (userId) {
      fetchCartOnLogin(userId);
      document.getElementById('sign-in-btn').style.display = 'none';
      document.getElementById('profile-icon').style.display = 'block';
    }

    // Scroll button functionality
    const scrollUpBtn = document.getElementById('scrollUpBtn');
    window.onscroll = () => {
      if (document.body.scrollTop > 20 || document.documentElement.scrollTop > 20) {
        scrollUpBtn.style.display = 'block';
      } else {
        scrollUpBtn.style.display = 'none';
      }
    };
    scrollUpBtn.onclick = () => {
      document.body.scrollTop = 0;
      document.documentElement.scrollTop = 0;
    };

    // Hamburger menu functionality
    const hamburger = document.getElementById('hamburger');
    const mobileMenu = document.getElementById('mobileMenu');
    hamburger.onclick = () => {
      setIsMobileMenuOpen(!isMobileMenuOpen);
    };

    // Login/Signup and forgot password functionality
    const signInBtn = document.getElementById('sign-in-btn');
    const closeBtn = document.getElementById('close-btn');
    const switchToSignup = document.getElementById('switch-to-signup');
    const switchToLogin = document.getElementById('back-to-login');
    const forgotPasswordLink = document.getElementById('forgot-password-link');
    const closeForgotPasswordBtn = document.getElementById('close-forgot-password-btn');

    if (signInBtn) {
      signInBtn.onclick = () => setIsLoginPopupVisible(true);
    }
    if (closeBtn) {
      closeBtn.onclick = () => setIsLoginPopupVisible(false);
    }
    if (switchToSignup) {
      switchToSignup.onclick = () => {
        setIsSignup(true);
        document.getElementById('name').style.display = 'block';
        document.getElementById('popup-title').innerText = 'Signup';
        document.getElementById('submit-btn').innerText = 'Signup';
        document.getElementById('switch-action').innerHTML = 'Already have an account? <span id="switch-to-login">Login here</span>';
        const switchToLoginInner = document.getElementById('switch-to-login');
        if (switchToLoginInner) {
          switchToLoginInner.onclick = () => {
            setIsSignup(false);
            document.getElementById('name').style.display = 'none';
            document.getElementById('popup-title').innerText = 'Login';
            document.getElementById('submit-btn').innerText = 'Login';
            document.getElementById('switch-action').innerHTML = 'Create a new account? <span id="switch-to-signup">Click here</span>';
          };
        }
      };
    }
    if (switchToLogin) {
      switchToLogin.onclick = () => setIsLoginPopupVisible(true);
    }
    if (forgotPasswordLink) {
      forgotPasswordLink.onclick = () => {
        setIsLoginPopupVisible(false);
        setIsForgotPasswordPopupVisible(true);
      };
    }
    if (closeForgotPasswordBtn) {
      closeForgotPasswordBtn.onclick = () => setIsForgotPasswordPopupVisible(false);
    }

    // Profile icon functionality
    const profileIcon = document.getElementById('profile-icon');
    if (profileIcon) {
      profileIcon.onclick = () => setShowProfileOptions(!showProfileOptions);
    }

    // Logout functionality
    const logoutOption = document.getElementById('logout-option');
    if (logoutOption) {
      logoutOption.onclick = () => {
        localStorage.removeItem('userId');
        document.getElementById('sign-in-btn').style.display = 'block';
        document.getElementById('profile-icon').style.display = 'none';
        setShowProfileOptions(false);
        setCartItems({});
        localStorage.removeItem('cartItems');
        renderCartItems();
        updateCartTotal();
        updateCartIndicator();
      };
    }

    // Active link functionality
    const links = document.querySelectorAll('.navbar-menu a');
    links.forEach(link => {
      if (link.href === window.location.href) {
        link.classList.add('active');
      }
    });

    // Load functionality
    const body = document.body;
    body.classList.add('loaded');

    // Place order functionality
    const checkoutBtn = document.getElementById('checkout-btn');
    if (checkoutBtn) {
      checkoutBtn.onclick = () => {
        const userId = localStorage.getItem('userId');
        if (!userId) {
          alert('Please sign in to place an order.');
          return;
        }
        window.location.href = '/order';
      };
    }

  }, []);

  useEffect(() => {
    saveCartToLocalStorage();
  }, [cartItems]);

  const updateCartIndicator = () => {
    const dot = document.querySelector('.dot');
    if (!dot) return;
    dot.style.display = Object.keys(cartItems).length > 0 ? 'block' : 'none';
  };

  const renderMenu = () => {
    const menuListContainer = document.getElementById('explore-menu-list');
    if (!menuListContainer) return;
    menuListContainer.innerHTML = "";

    menuList.forEach(item => {
      const menuItem = document.createElement('div');
      menuItem.classList.add('explore-menu-list-item');

      const img = document.createElement('img');
      img.src = item.menu_image;
      img.alt = item.menu_name;
      img.classList.toggle("active", category === item.menu_name);
      img.classList.toggle("inactive", category !== item.menu_name);

      menuItem.appendChild(img);

      const p = document.createElement('p');
      p.innerText = item.menu_name;
      menuItem.appendChild(p);

      menuItem.addEventListener('click', () => {
        setCategory(category === item.menu_name ? "All" : item.menu_name);
      });

      menuListContainer.appendChild(menuItem);
    });
  };

  const renderFoodItems = () => {
    const foodListContainer = document.getElementById("food-display-list");
    if (!foodListContainer) return;
    foodListContainer.innerHTML = "";

    const filteredItems = foodList.filter(item => category === "All" || item.category === category);
    if (filteredItems.length === 0) {
      foodListContainer.innerHTML = "<h1 class='empty-message'>No items found.</h1>";
      return;
    }

    filteredItems.forEach(item => {
      const foodItem = document.createElement("div");
      foodItem.classList.add("food-item");

      const imgContainer = document.createElement("div");
      imgContainer.classList.add("food-item-img-container");

      const img = document.createElement("img");
      img.src = item.image;
      img.alt = item.name;
      img.classList.add("food-item-image");

      let cartControl;
      if (!cartItems[item._id]) {
        cartControl = document.createElement("img");
        cartControl.src = "assets/add_icon_white.png";
        cartControl.classList.add("add");
        cartControl.addEventListener("click", () => addToCart(item._id));
      } else {
        cartControl = document.createElement("div");
        cartControl.classList.add("food-item-counter");

        const removeBtn = document.createElement("img");
        removeBtn.src = "assets/remove_icon_red.png";
        removeBtn.addEventListener("click", () => removeFromCart(item._id));

        const qty = document.createElement("p");
        qty.innerText = cartItems[item._id];

        const addBtn = document.createElement("img");
        addBtn.src = "assets/add_icon_green.png";
        addBtn.addEventListener("click", () => addToCart(item._id));

        cartControl.appendChild(removeBtn);
        cartControl.appendChild(qty);
        cartControl.appendChild(addBtn);
      }

      imgContainer.appendChild(img);
      imgContainer.appendChild(cartControl);

      const foodInfo = document.createElement("div");
      foodInfo.classList.add("food-item-info");

      const nameRatingContainer = document.createElement("div");
      nameRatingContainer.classList.add("food-item-name-rating");

      const name = document.createElement("p");
      name.innerText = item.name;

      const ratingImg = document.createElement("img");
      ratingImg.src = "assets/rating_starts.png";

      nameRatingContainer.appendChild(name);
      nameRatingContainer.appendChild(ratingImg);

      const description = document.createElement("p");
      description.classList.add("food-item-desc");
      description.innerText = item.description;

      const price = document.createElement("p");
      price.classList.add("food-item-price");
      price.innerText = `£${item.price}`;

      foodInfo.appendChild(nameRatingContainer);
      foodInfo.appendChild(description);
      foodInfo.appendChild(price);

      foodItem.appendChild(imgContainer);
      foodItem.appendChild(foodInfo);
      foodListContainer.appendChild(foodItem);
    });
  };

  const fetchCartOnLogin = (userId) => {
    fetch(`http://localhost:5000/cart/${userId}`)
      .then(response => response.json())
      .then(data => {
        console.log('Fetched cart data on login:', data);
        const newCartItems = {};
        if (data && data.items) {
          data.items.forEach(item => {
            newCartItems[item.foodItemId] = item.quantity;
          });
        }
        setCartItems(newCartItems);
        localStorage.setItem('cartItems', JSON.stringify(newCartItems));
        updateCartIndicator();
        renderFoodItems();
        renderCartItems();
        updateCartTotal();
      })
      .catch(error => {
        console.error('Error fetching cart on login:', error);
        loadCartFromLocalStorage();
      });
  };

  const loadCartFromLocalStorage = () => {
    const storedCart = localStorage.getItem('cartItems');
    if (storedCart) {
      setCartItems(JSON.parse(storedCart));
    }
  };

  const addToCart = (id) => {
    const userId = localStorage.getItem('userId');
    if (!userId) {
      alert('Please sign in to add items to your cart.');
      setIsLoginPopupVisible(true);
      return;
    }

    const foodItem = foodList.find(item => item._id === id);
    if (!foodItem) {
      console.error('Food item not found:', id);
      return;
    }

    const itemToAdd = {
      userId: userId,
      foodItemId: foodItem._id,
      name: foodItem.name,
      price: foodItem.price
    };

    fetch('http://localhost:5000/cart/add', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(itemToAdd)
    })
    .then(response => response.json())
    .then(data => {
      console.log('Item added to cart on server:', data);
      setCartItems(prevCartItems => ({
        ...prevCartItems,
        [id]: (prevCartItems[id] || 0) + 1
      }));
    })
    .catch(error => {
      console.error('Error adding item to cart:', error);
      alert('Failed to add item to cart. Please try again.');
    });
  };

  const removeFromCart = (id) => {
    const userId = localStorage.getItem('userId');
    if (!userId) {
      alert('Please sign in.');
      setIsLoginPopupVisible(true);
      return;
    }

    fetch('http://localhost:5000/cart/remove', {
      method: 'DELETE',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ userId: userId, foodItemId: id })
    })
    .then(response => response.json())
    .then(data => {
      console.log('Item removed from cart on server:', data);
      setCartItems(prevCartItems => {
        const newCartItems = { ...prevCartItems };
        if (newCartItems[id]) {
          newCartItems[id]--;
          if (newCartItems[id] === 0) {
            delete newCartItems[id];
          }
        }
        return newCartItems;
      });
    })
    .catch(error => {
      console.error('Error removing item from cart:', error);
      alert('Failed to remove item from cart. Please try again.');
    });
  };

  const saveCartToLocalStorage = () => {
    localStorage.setItem('cartItems', JSON.stringify(cartItems));
    updateCartIndicator();
  };

  const renderCartItems = () => {
    const cartItemsList = document.getElementById('cart-items-list');
    if (!cartItemsList) return;
    cartItemsList.innerHTML = '';

    Object.keys(cartItems).forEach(id => {
      if (cartItems[id] > 0) {
        const item = foodList.find(food => food._id === id);
        if (item) {
          const cartItemDiv = document.createElement('div');
          cartItemDiv.classList.add('cart-items-title', 'cart-items-item');

          const img = document.createElement('img');
          img.src = item.image;
          img.alt = item.name;

          const name = document.createElement('p');
          name.innerText = item.name;

          const price = document.createElement('p');
          price.innerText = `£${item.price}`;

          const quantity = document.createElement('p');
          quantity.innerText = `${cartItems[id]}`;

          const total = document.createElement('p');
          total.innerText = `£${item.price * cartItems[id]}`;

          const addButton = document.createElement('p');
          addButton.classList.add('plus');
          addButton.innerText = '+';
          addButton.addEventListener('click', () => addToCart(id));

          const removeButton = document.createElement('p');
          removeButton.classList.add('cross');
          removeButton.innerText = 'x';
          removeButton.addEventListener('click', () => removeFromCart(id));

          cartItemDiv.appendChild(img);
          cartItemDiv.appendChild(name);
          cartItemDiv.appendChild(price);
          cartItemDiv.appendChild(quantity);
          cartItemDiv.appendChild(total);
          cartItemDiv.appendChild(addButton);
          cartItemDiv.appendChild(removeButton);

          cartItemsList.appendChild(cartItemDiv);
        }
      }
    });
  };

  const getTotalCartAmount = () => {
    return Object.keys(cartItems).reduce((total, id) => {
      const item = foodList.find(food => food._id === id);
      return item ? total + item.price * cartItems[id] : total;
    }, 0);
  };

  const updateCartTotal = () => {
    const subTotal = getTotalCartAmount();
    const deliveryFee = subTotal === 0 ? 0 : 2;
    const total = subTotal + deliveryFee;

    const subTotalElement = document.getElementById('sub-total');
    const deliveryFeeElement = document.getElementById('delivery-fee');
    const totalElement = document.getElementById('total');

    if (subTotalElement) subTotalElement.textContent = `£${subTotal}`;
    if (deliveryFeeElement) deliveryFeeElement.textContent = `£${deliveryFee}`;
    if (totalElement) totalElement.textContent = `£${total}`;
  };

  const handleApplyPromo = () => {
    const promoCodeElement = document.getElementById('promo-code');
    const promoCode = promoCodeElement ? promoCodeElement.value : '';
    alert(`Promo code applied: ${promoCode}`);
  };

  return (
    <div>
      <div id="login-popup" className="login-popup" style={{ display: isLoginPopupVisible ? 'block' : 'none' }}>
        <form id="login-popup-container" className="login-popup-container">
          <div className="login-popup-title">
            <h2 id="popup-title">{isSignup ? 'Signup' : 'Login'}</h2>
            <img id="close-btn" src="assets/cross_icon.png" alt="Close" />
          </div>
          <div id="login-popup-inputs" className="login-popup-inputs">
            {isSignup && <input type="text" id="name" placeholder="Your name" required />}
            <input type="email" id="email" placeholder="Your email" required />
            <input type="password" id="password" placeholder="Password" required />
          </div>
          <div className="login-popup-forgot" id="forgot-password-container-link">
            <a href="#" id="forgot-password-link" style={{ textDecoration: 'none', cursor: 'pointer', color: 'tomato' }}>Forgot Password?</a>
          </div>
          <button id="submit-btn">{isSignup ? 'Signup' : 'Login'}</button>
          <div className="login-popup-condition">
            <input id="check-box" type="checkbox" required />
            <p>By continuing, I agree to the terms of use & privacy policy.</p>
          </div>
          <p id="switch-action">
            {isSignup ? 'Already have an account? <span id="switch-to-login">Login here</span>' : 'Create a new account? <span id="switch-to-signup">Click here</span>'}
          </p>
        </form>
      </div>

      <div id="forgot-password-popup" className="login-popup" style={{ display: isForgotPasswordPopupVisible ? 'block' : 'none' }}>
        <form id="forgot-password-container" className="login-popup-container">
          <div className="login-popup-title">
            <h2>Forgot Password</h2>
            <img id="close-forgot-password-btn" src="assets/cross_icon.png" alt="Close" />
          </div>
          <div className="login-popup-inputs">
            <input type="email" id="forgot-email" placeholder="Your email" required />
            <input type="password" id="new-forgot-password" placeholder="New Password" required />
          </div>
          <button id="reset-password-btn">Reset Password</button>
          <p>
            Remember your password? <span id="back-to-login" style={{ cursor: 'pointer', color: 'tomato' }}>Login here</span>
          </p>
        </form>
      </div>

      <div className="app">
        <div className="navbar">
          <img id="logo" src="assets/logo.png" alt="Company Logo" className="logo" />
          <ul className="navbar-menu">
            <a href="home.html" id="home" className="active">home</a>
            <a href="#explore-menu" id="menu">menu</a>
            <a href="#app-download" id="mobile-app">mobile-app</a>
            <a href="#footer" id="contact-us">contact us</a>
          </ul>
          <div className="navbar-right">
            <img id="search-icon" src="assets/search_icon.png" alt="Search" />
            <div className="navbar-search-icon">
              <a href="cart.html">
                <img id="basket-icon" src="assets/basket_icon.png" alt="Basket" />
              </a>
              <div className="dot"></div>
            </div>
            <div style={{ position: 'relative' }}>
              <button id="sign-in-btn">Sign In</button>
              <img id="profile-icon" src="assets/profile_icon.png" alt="Profile" style={{ display: localStorage.getItem('userId') ? 'block' : 'none' }} />
              <div id="profile-options" className="profile-options" style={{ display: showProfileOptions ? 'block' : 'none' }}>
                <div id="bag-option">
                  <a href="my_orders.html" style={{ textDecoration: 'none', color: 'black' }}>
                    <img className="orders-img" src="assets/bag_icon.png" alt="My Orders" />
                    <span className="orders">Orders</span>
                  </a>
                </div>
                <div id="logout-option">
                  <img className="logout-img" src="assets/logout_icon.png" alt="Logout" />
                  <span className="logout">Logout</span>
                </div>
              </div>
            </div>
          </div>
        </div>

        <div className="hamburger" id="hamburger">
          ☰
        </div>

        <div className="mobile-menu" id="mobileMenu" style={{ display: isMobileMenuOpen ? 'block' : 'none' }}>
          <a href="home.html">home</a>
          <a href="#explore-menu">menu</a>
          <a href="#app-download">mobile-app</a>
          <a href="#footer">contact us</a>
        </div>

        <div className="header">
          <div className="header-contents">
            <h2>Order your favourite food here</h2>
            <p>
              Choose from a diverse menu featuring a delectable array of dishes
              crafted with the finest ingredients and culinary expertise. Our
              mission is to satisfy your cravings and elevate your dining
              experience, one delicious meal at a time.
            </p>
            <a href="#explore-menu">
              <button id="view-menu-btn">View Menu</button>
            </a>
          </div>
        </div>
        <section id="exploremenu">
          <div id="explore-menu" className="explore-menu">
            <h1>Explore our menu</h1>
            <p className="explore-menu-text">
              Craving something tasty? Our menu is packed with a diverse selection of flavorful dishes made from
              the
              freshest ingredients. Whether you're in the mood for classic comfort food, exotic international
              flavors,
              or healthy choices, we've got something for everyone. Explore our menu and indulge in a delightful
              dining experience!
            </p>
            <div id="explore-menu-list" className="explore-menu-list">
              {/* Menu items will be inserted here */}
            </div>
            <hr />
          </div>
        </section>

        <div className="food-display" id="food-display">
          <h2>Top dishes near you</h2>
          <div id="food-display-list" className="food-display-list">
            {/* Food items will be inserted here */}
          </div>
        </div>

        <section id="mobileapp">
          <div className="app-download" id="app-download">
            <p>For Better Experience Download <br /> EatCo. App</p>
            <div className="app-download-platforms">
              <img id="play-store" src={assets.play_store} alt="Play Store" />
              <img id="app-store" src="assets/app_store.png" alt="App Store" />
            </div>
          </div>
        </section>
      </div>

      <section id="contactus">
        <div className="footer" id="footer">
          <div className="footer-content">
            <div className="footer-content-left">
              <img className="footer-logo" src="assets/logo.png" alt="Eatco Logo" />
              <p>Delicious meals, delivered to your door. Fresh ingredients, great flavors, and fast
                service—because you deserve the best!</p>
              <div className="footer-social-icons">
                <img src="assets/facebook_icon.png" alt="Facebook" />
                <img src="assets/twitter_icon.png" alt="Twitter" />
                <img src="assets/linkedin_icon.png" alt="LinkedIn" />
              </div>
            </div>
            <div className="footer-content-center">
              <h2>COMPANY</h2>
              <ul>
                <li>Home</li>
                <li>About us</li>
                <li>Delivery</li>
                <li>Privacy policy</li>
              </ul>
            </div>
            <div className="footer-content-right">
              <h2>GET IN TOUCH</h2>
              <ul>
                <li>+4401234567890</li>
                <li>contact@eatco.com</li>
              </ul>
            </div>
          </div>
          <hr />
          <p className="footer-copyright">Copyright 2025 &copy; Eatco.com - All Rights Reserved.</p>
        </div>
      </section>

      <button id="scrollUpBtn">↑</button>
      <div id="cart-total">
        <p id="sub-total"></p>
        <p id="delivery-fee"></p>
        <p id="total"></p>
      </div>
      <button id="checkout-btn">Checkout</button>
      <div>
        <input type="text" id="promo-code" />
        <button id="apply-promo">Apply Promo</button>
      </div>
    </div>
  );
}

export default Home;
